package dustin.cex.domains.kyc;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.edd.*;
import dustin.cex.domains.auth.model.entity.UserRole;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.web.server.ResponseStatusException;

/** 승인 전 공개 금지·정확한 현재 근거·문구 암호화·감사 롤백을 실제 DB에서 검증한다. */
class CustomerFinalDraftIntegrationTest extends CustomerFinalTestSupport {
    @Test void designatedCheckerReceivesExactDraftAndActualBasisOnly() throws Exception {
        var r=draft();var seen=finals.inspect(checker.user().getId(),checker.sid(),r.payload().id());assertEquals(explanation(),seen.explanation());assertEquals(note.id(),seen.note().note().id());assertEquals(receipt.id(),seen.customerReason().receipt().id());assertEquals("PENDING",r.status());assertEquals(1,active());blocked();assertEquals(List.of(reply),replies.own(customer.getId(),sid,receipt.id(),0));
    }
    @Test void metadataAndDatabaseDoNotExposePublicDraftPlaintext() throws Exception {var r=draft();assertFalse(json.writeValueAsString(r).contains(explanation().text()));assertFalse(jdbc.queryForObject("SELECT payload FROM customer_review_final_requests WHERE id=?",String.class,r.payload().id()).contains(explanation().text()));assertFalse(new String(jdbc.queryForObject("SELECT explanation_cipher FROM customer_review_final_requests WHERE id=?",byte[].class,r.payload().id()),java.nio.charset.StandardCharsets.UTF_8).contains(explanation().text()));assertFalse(explanation().toString().contains(explanation().text()));}
    @Test void sameKeyReplaysAndChangedTextOrNoteConflicts(){UUID key=UUID.randomUUID();var r=finals.propose(maker.user().getId(),maker.sid(),receipt.id(),key,note.id(),explanation());assertEquals(r,finals.propose(maker.user().getId(),maker.sid(),receipt.id(),key,note.id(),explanation()));assertThrows(ResponseStatusException.class,()->finals.propose(maker.user().getId(),maker.sid(),receipt.id(),key,note.id(),new CustomerFinalReviewService.Explanation("다른 문구")));assertThrows(ResponseStatusException.class,()->finals.propose(maker.user().getId(),maker.sid(),receipt.id(),key,UUID.randomUUID(),explanation()));}
    @Test void outsidersAndMakerCannotInspectCheckerDraft(){var r=draft();for(var a:List.of(maker,independent,nextChecker))assertThrows(ResponseStatusException.class,()->finals.inspect(a.user().getId(),a.sid(),r.payload().id()));assertThrows(ResponseStatusException.class,()->finals.propose(checker.user().getId(),checker.sid(),receipt.id(),UUID.randomUUID(),note.id(),explanation()));}
    @Test void anotherPendingDraftIsRejected(){draft();assertThrows(ResponseStatusException.class,this::draft);}
    @Test void staleOrForeignNoteCannotBeProposed(){assertThrows(ResponseStatusException.class,()->finals.propose(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),UUID.randomUUID(),explanation()));notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"새로운 내부 근거"));assertThrows(ResponseStatusException.class,this::draft);}
    @Test void newNoteInvalidatesExistingInspection(){var r=draft();notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"추가 근거"));assertThrows(ResponseStatusException.class,()->finals.inspect(checker.user().getId(),checker.sid(),r.payload().id()));}
    @Test void changedOriginalFinancialBasisInvalidatesDraft() throws Exception {var r=draft();approveWithdrawal(withdraw(UUID.randomUUID()));assertThrows(ResponseStatusException.class,()->finals.inspect(checker.user().getId(),checker.sid(),r.payload().id()));}
    @Test void transferredCustodyInvalidatesDraft() throws Exception {var r=draft();transfer();assertThrows(ResponseStatusException.class,()->finals.inspect(nextChecker.user().getId(),nextChecker.sid(),r.payload().id()));assertThrows(ResponseStatusException.class,()->finals.inspect(checker.user().getId(),checker.sid(),r.payload().id()));}
    @Test void newOwnerWithoutPersonalReasonViewCannotCreateDraft() throws Exception {transfer();var n=notes.list(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),0).getFirst();assertThrows(ResponseStatusException.class,()->finals.propose(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),UUID.randomUUID(),n.id(),explanation()));}
    @Test void invalidPublicTextIsRejected(){for(String v:List.of(" ","a\u0000b","a\u202eb","x".repeat(2001)))assertThrows(ResponseStatusException.class,()->finals.propose(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),note.id(),new CustomerFinalReviewService.Explanation(v)));}
    @Test void missingCurrentCheckerDoesNotChooseUnassignedApprover(){disable(checker);assertThrows(ResponseStatusException.class,this::draft);}
    @Test void proposalAuditFailureRollsBackDraftAndApprovalBinding(){doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_FINAL_PROPOSED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,this::draft);reset(audit);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_review_final_requests WHERE review_id=?",Long.class,receipt.id()));assertNotNull(draft());}
    @Test void inspectionAuditFailureRollsBackBothPersonalAndDraftViews(){var r=draft();long before=jdbc.queryForObject("SELECT count(*) FROM customer_exit_review_views WHERE request_id=?",Long.class,receipt.id());doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_FINAL_VIEWED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->finals.inspect(checker.user().getId(),checker.sid(),r.payload().id()));reset(audit);assertEquals(before,jdbc.queryForObject("SELECT count(*) FROM customer_exit_review_views WHERE request_id=?",Long.class,receipt.id()));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_review_final_views WHERE request_id=?",Long.class,r.payload().id()));}
    @Test void currentSessionAndAccountVersionAreRequired(){var r=draft();assertThrows(ResponseStatusException.class,()->finals.inspect(checker.user().getId(),maker.sid(),r.payload().id()));var u=users.findById(checker.user().getId()).orElseThrow();u.setUsername("검토자 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->finals.inspect(checker.user().getId(),checker.sid(),r.payload().id()));}
    @Test void allNewHistoryTablesRejectUpdateDeleteAndTruncate(){draft();for(String table:List.of("customer_review_final_requests","customer_review_final_views","customer_review_final_decisions"))for(String command:List.of("UPDATE "+table+" SET "+(table.endsWith("requests")?"id=id":table.endsWith("views")?"id=id":"request_id=request_id"),"DELETE FROM "+table,"TRUNCATE "+table+" CASCADE"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(command));}
    @Test void httpDraftUsesRoleBoundaryAndNoStore() throws Exception {var r=draft();String path="/api/admin/compliance/customer-final-requests/"+r.payload().id()+"/inspect";mvc.perform(post(path).header("Authorization","Bearer "+checker.access())).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store")));mvc.perform(post(path).header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());mvc.perform(get("/api/admin/compliance/customer-final-requests/"+r.payload().id()).header("Authorization","Bearer "+customerAccess)).andExpect(status().isForbidden());}
}
